import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
best = 0
for i in range(n):
    c = {}
    for j in range(i, n):
        c[a[j]] = c.get(a[j], 0) + 1
        if c[a[j]] > k:
            break
        best = max(best, j - i + 1)
print(best)

